/// A geometry path that contains the number of path points in the path, a list of all the path points, and whether the path is open.
///
/// Schema: `GeometryPathType_TypeDef` in `datatype.rnc`.
///
/// Since IDML 6.0.
#[derive(Debug, Clone, PartialEq)]
pub struct GeometryPathType {
    /// `@PathOpen`: `xsd:boolean`. Since IDML 6.0.
    pub path_open: bool,
    /// `<PathPointArray>`. Since IDML 6.0.
    pub path_point_array: Vec<PathPointType>,
}

impl GeometryPathType {
    /// A value with the required data; everything optional is absent.
    pub fn new(path_open: bool) -> Self {
        Self {
            path_open,
            path_point_array: Vec::new(),
        }
    }

    #[inline(never)]
    fn read_attributes(r: &mut Reader<'_, '_, '_>, v: &mut Self) -> Result<(), Error> {
        v.path_open = r.attr("PathOpen")?;
        Ok(())
    }

    #[inline(never)]
    fn write_attributes(&self, w: &mut Writer) -> Result<(), Error> {
        w.attr("PathOpen", &self.path_open)?;
        Ok(())
    }
}

impl Content for GeometryPathType {
    fn placeholder() -> Self {
        Self { path_open: false, path_point_array: Vec::new() }
    }

    fn read_into(r: &mut Reader<'_, '_, '_>, v: &mut Self) -> Result<(), Error> {
        r.known(&["PathPointArray"])?;
        Self::read_attributes(r, v)?;
        v.path_point_array = r.elem("PathPointArray", |r| r.elems("PathPointType", PathPointType::read))?;
        Ok(())
    }

    fn write(&self, w: &mut Writer) -> Result<(), Error> {
        self.write_attributes(w)?;
        let v = &self.path_point_array; w.elem("PathPointArray", |w| v.iter().try_for_each(|x0| w.elem("PathPointType", |w| x0.write(w))))?;
        Ok(())
    }
}

