/// The bounds of a rectangle specified in unit type in the form \[top, left, bottom, right\].
///
/// Schema: `UnitRectangleBoundsType_TypeDef` in `datatype.rnc`.
///
/// Since IDML 6.0.
#[derive(Debug, Clone, PartialEq)]
pub struct UnitRectangleBoundsType {
    /// `@Top`: `xsd:double`. Since IDML 6.0.
    pub top: f64,
    /// `@Left`: `xsd:double`. Since IDML 6.0.
    pub left: f64,
    /// `@Bottom`: `xsd:double`. Since IDML 6.0.
    pub bottom: f64,
    /// `@Right`: `xsd:double`. Since IDML 6.0.
    pub right: f64,
}

impl UnitRectangleBoundsType {
    /// A value with the required data; everything optional is absent.
    pub fn new(top: f64, left: f64, bottom: f64, right: f64) -> Self {
        Self {
            top,
            left,
            bottom,
            right,
        }
    }
}

impl Content for UnitRectangleBoundsType {
    fn placeholder() -> Self {
        Self { top: 0.0, left: 0.0, bottom: 0.0, right: 0.0 }
    }

    fn read_into(r: &mut Reader<'_, '_, '_>, v: &mut Self) -> Result<(), Error> {
        v.top = r.attr("Top")?;
        v.left = r.attr("Left")?;
        v.bottom = r.attr("Bottom")?;
        v.right = r.attr("Right")?;
        Ok(())
    }

    fn write(&self, w: &mut Writer) -> Result<(), Error> {
        w.attr("Top", &self.top)?;
        w.attr("Left", &self.left)?;
        w.attr("Bottom", &self.bottom)?;
        w.attr("Right", &self.right)?;
        Ok(())
    }
}

